INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-B100 / BJPX-B150 / BJPX-B200 / BJPX-B250', 'Biochemistry Incubator 100L 150L 200L 250L', 'General thermostatic biochemistry incubator for BOD determination, microbial culture, preservation, plant cultivation, and breeding experiments. Features a 7-inch touch controller, double-glass door design, automatic defrosting, and over-temperature protection for reliable laboratory operation.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/pictures/BJPX-C50.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-C50 / BJPX-C80 / BJPX-C160 / BJPX-C80S / BJPX-C160S', 'CO2 Incubator BJPX-C50 BJPX-C80 BJPX-C160 BJPX-C80S BJPX-C160S', 'CO2 incubator range for contamination-controlled cell culture, with air-jacket and water-jacket configurations. Uses dual-channel IR CO2 sensing, touchscreen control, alarm protections, and stainless-steel chamber options for stable long-term growth conditions.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/products/co2-incubator-bjpx-c50-bjpx-c80-bjpx-c160-bjpx-c80s-bjpx-c160s.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-C80III / BJPX-C160III', 'CO2 Incubator 80L 160L (Low Temperature Series)', 'Low-temperature air-jacket CO2 incubators with UV sterilization, segmented program control, anti-icing evaporator design, and uniform all-side heating for stable cell culture performance. Includes comprehensive safety alarms and IR CO2 measurement.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/pictures/BJPX-HDO43.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-C100M / BJPX-C160M / BJPX-C200M / BJPX-C260M / BJPX-C300M', 'CO2 Incubator Medical Series 100L 160L 200L 260L 300L', 'Medical-series air-jacket CO2 incubators designed to simulate in-vivo growth conditions with stable temperature, CO2 concentration, and humidity. Features 90C moist heat sterilization, HEPA-assisted gas quality, 3D airflow, and multi-door architecture to reduce exchange loss.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/Supplies/CO2 Incubator Medical Series 100L 160L 200L 260L 300L.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-H54BK(D/G) / BJPX-H88BK(D/G) / BJPX-H160BK(D/G) / BJPX-H200BK(G) / BJPX-H270BK(D/G)', 'Touch Screen Constant-Temperature Incubator', 'Constant-temperature incubator range with LCD touch control, stainless chamber, test port, and over-temperature safety protection. D-type units include an inner glass door while G-type units include a viewing window for convenient observation.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/pictures/BK-200-8.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-HT80BII / BJPX-HT100BII / BJPX-HT150BII / BJPX-HT200BII / BJPX-HT250BII / BJPX-HT300BII / BJPX-HT400BII', 'Constant Temperature and Humidity Incubator', 'Precise temperature-and-humidity incubator for biotechnology, stability testing, sterile tests, food processing, and industrial material studies. Built with PID microcomputer control, stainless chamber, tempered glass inner door, and integrated safety alarm system.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/Supplies/Constant Temperature and Humidity Incubator.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-L200BK / BJPX-L200BKII', 'Lighting Incubator BJPX-L200BK / BJPX-L200BKII', '200L lighting incubators with adjustable LED cold-light illumination for day/night simulation and stable growth conditions. Includes forced convection, PID control, lockable operation interface, and eco-friendly refrigeration design.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/products/lighting-incubator-bjpx-l200bk-bjpx-l200bkii.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-ST10-L / BJPX-ST11-L / BJPX-ST10 / BJPX-ST11 / BJPX-ST20', 'Small Capacity Thermostatic Shaking Incubator (BJPX-ST Series)', 'Compact thermostatic shaking incubators for microbiology, molecular biology, and cell culture workflows requiring controlled temperature and uniform agitation. Features PID control, historical data/export, smooth high-speed operation, and door-open auto-stop protection.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Incubators', '1 unit', 0, '/Supplies/Small Capacity Thermostatic Shaking Incubator (BJPX-ST Series).jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BBR-4V626 / BBR-4V966', 'Blood Bank Refrigerator (Double Door)', 'Blood bank refrigerator series for hospitals, blood banks, and laboratories requiring stable 2 to 6C storage. Features multi-sensor monitoring, electric heated glass doors, forced-air refrigeration, classified basket storage, and comprehensive alarm protection.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Refrigerators', '1 unit', 0, '/Supplies/Blood Bank Refrigerator (Double Door).jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-40V58 / BDF-40V90 / BDF-40V208 / BDF-40V268', '-40C Low Temperature Freezer (V Series)', 'Two-room -40C low temperature freezer series with independent temperature control for separated sample storage. Designed for reliable low-temperature preservation with microprocessor control, direct-cooling, and manual defrost.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/products/40c-low-temperature-freezer-v-series.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BBR Series', 'Blood Bank Refrigerator BBR Series', 'Specialized blood bank refrigeration units designed to store blood and blood products at precise and stable temperatures. Suitable for hospitals, blood banks, research laboratories, and clinical facilities requiring safe storage of critical biological materials.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Refrigerators', '1 unit', 0, '/Supplies/Blood Bank Refrigerator BBR Series.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-25 Separate Refrigerator Series', '-25C Freezer (Separate Refrigerator) 300L 318L 368L 450L', 'Separate-compartment -25C freezer series for scientific research, frozen plasma, vaccines, and biological products. Suitable for research institutes, hospitals, university laboratories, and industrial low-temperature testing.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/Supplies/-25C Freezer (Separate Refrigerator) 300L 318L 368L 450L.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-20V40 / BDF-25V230 / BDF-25V300', '-20/25C Freezer (Economic Type)', 'Cost-effective -20/-25C freezer series for laboratories, hospitals, research institutes, and industrial storage. Provides reliable direct-cooling performance with microprocessor control and essential safety alarms.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/Supplies/-20:25C FREEZER (Economic Type).webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BPR-5V288S / BPR-5V298 / BPR-5V358S / BPR-5V368 / BPR-5V468', 'Laboratory Refrigerator 288L 298L 358L 368L 468L', 'Laboratory refrigerator series for reagents, media, proteins, and biomedical samples in research, clinical, and industrial laboratories. Built with air-cooling, automatic defrost, precise microprocessor control, and electrically heated glass doors.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Refrigerators', '1 unit', 0, '/pictures/BPR-5V118.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BPR-5V628 / BPR-5V650 / BPR-5V968', 'Laboratory Refrigerator (Large Capacity)', 'Large-capacity laboratory refrigerator series for high-volume biomedical and reagent storage with stable 2 to 8C control, dual heated glass doors, automatic defrost, and integrated alarm protection.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Refrigerators', '1 unit', 0, '/Supplies/Laboratory Refrigerator (Large Capacity).webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-25V100 / BDF-25V270 / BDF-25V350 / BDF-25V936', '-25C Freezer Series', '-25C freezer series for scientific research, plasma, vaccines, and biological products. Covers compact to ultra-large capacities with microprocessor control, direct-cooling architecture, and model-specific alarm and backup options.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/Supplies/-25C Freezer Series.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-30V368D / BDF-30V528D', '-30C Freezer 368L 528L', 'Dual-chamber -30C freezer series for vaccines, blood products, and biological samples requiring stable low-temperature storage. Features microprocessor control, dual-compressor architecture, USB interface, and independent chamber refrigerant circuits.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/Supplies/-30C Freezer 368L 528L.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-40H110 / BDF-40H210 / BDF-40H310 / BDF-40H485', '-40C Freezer (H Series)', 'Horizontal -40C freezer series with independent temperature control concept for multi-sample storage needs. Provides stable direct-cooling performance, stainless interior, and safety alarms for laboratory and industrial cold-chain use.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/Supplies/-40C Freezer (H Series).webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
