INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BDF-86V168T / BDF-86V348T', '-86C Ultra-Low Freezer', 'Ultra-low temperature freezer series designed for high-value temperature-sensitive samples in scientific research, medical, and biotechnology settings. Supports deep-freeze preservation with dual compressors and multiple safety alarms.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Freezers', '1 unit', 0, '/Supplies/-86C Ultra-Low Freezer.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BJPX-SH23 / BJPX-SH55 / BJPX-SH88 / BJPX-SH105 / BJPX-SH140 / BJPX-SH200', 'Hot Air Sterilizer', 'Forced-convection hot air sterilizer series for high-temperature sterilization of glassware, metal instruments, powders, ointments, and other heat-stable items. Offers precise PT100 control, timing operation, and viewing window monitoring.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Sterilizers', '1 unit', 0, '/Supplies/Hot Air Sterilizer.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BKM-K18B / BKM-Z18B / BKM-K23B / BKM-Z23B', 'Table Top Class B Autoclave', 'Pulse-vacuum Class B table top autoclave series with multiple sterilization programs, high-efficiency vacuum system, safety interlocks, and real-time sterilization records via thermal printer and USB.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Autoclaves', '1 unit', 0, '/Supplies/Table Top Class B Autoclave.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BKM-K18N / BKM-K23N', 'Table Top Autoclave Class N Series', 'N-level gravity displacement table top sterilizer for stomatology, ophthalmology, beauty, and operating room use. Designed for glassware, bare metal utensils, and unwrapped solid instruments with straightforward cycle control.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Autoclaves', '1 unit', 0, '/Supplies/Table Top Autoclave Class N Series.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BKM-P18I / BKM-P18II / BKM-P18III / BKM-P24I / BKM-P24II / BKM-P24III', 'Portable Autoclave', 'Portable autoclave series for sterilizing surgical and dental instruments, glassware, media, dressings, and selected food/goods applications. Available in dual-use, anti-dry, and timing-control versions across 18L and 24L capacities.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Autoclaves', '1 unit', 0, '/Supplies/Portable Autoclave.jpeg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BKQ-B50BL / BKQ-B75BL / BKQ-B100BL / BKQ-B120BL', 'Biosafety Autoclave', 'Biosafety autoclave series for sterilizing materials, instruments, media, and waste while reducing biosafety contamination risk via integrated wastewater collection and waste-gas filtration systems.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Autoclaves', '1 unit', 0, '/Supplies/Biosafety Autoclave.webp') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BKQ-B50II / BKQ-B75II / BKQ-B100II / BKQ-B120II / BKQ-B150(II) / BKQ-B200(II)', 'Vertical Autoclave', 'Vertical gravity-displacement autoclave series for laboratory and inspection sterilization workflows. Includes real-time chamber temperature display, multiple sterilization programs, service-friendly design, and optional print recording.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Autoclaves', '1 unit', 0, '/Supplies/Vertical Autoclave.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BKQ-H150 / BKQ-H200 / BKQ-H300 / BKQ-H400', 'Horizontal Cylindrical Pressure Autoclave', 'Large horizontal pressure steam sterilizer with built-in steam generator and automatic water-to-drying workflow. Suitable for high-throughput sterilization with wrapped/unwrapped, dressing, rubber, drying, and custom solid programs.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Autoclaves', '1 unit', 0, '/Supplies/Horizontal Cylindrical Pressure Autoclave.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BK-Y-600 / BK-Y-800 / BK-Y-1000 / BK-Y-1300 / BKB-Y-800', 'Air Sterilizer BK-Y Series', 'Air sterilizer series for medical institutions, labs, production workshops, and public spaces, supporting manned or unmanned disinfection modes. Integrates UV, filtration, negative ions, and programmable operation segments.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Sterilizers', '1 unit', 0, '/pictures/FH1000(E)-1.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-001', '9mm 2ml Short Thread HPLC Autosampler Vial', '1.5-2.0ml short-thread HPLC/GC autosampler vial for Agilent and rotating/robotic arm samplers. Borosilicate/1st hydrolytic class glass, 12 x 32mm, clear or amber, 9mm screw neck, write-in patch, PTFE/silicone septa options and 250ul/300ul insert options.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/9mm 2ml Short Tread HPLC Autosampler Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-002', '9mm Short Thread Caps with Septa', 'Polypropylene screw caps for 9mm short-thread vials. Available with open centre hole for autosampler use or closed top for storage. Supplied/compatible with PTFE/silicone or PTFE/silicone/PTFE septa, pre-slit or non-slit options, and multiple cap colours.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/9mm Short Thread Caps with Septa.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-003', '8-425 2ml Screw Neck HPLC Autosampler Vial', '1.5-2.0ml screw-neck autosampler vial for HPLC/GC systems. 11.6 x 32mm, clear or amber borosilicate glass, 8mm screw neck, compatible with automated sample introduction systems and 150ul/250ul inserts.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/8-425 2ml Screw Neck HPLC Autosampler Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-004', 'Screw Caps with Septa for 8-425 Screw Neck Vial', 'Polypropylene screw caps for 8-425 screw vials. Available with 5.5mm centre hole or closed top, PTFE/silicone septa, 8 x 1.5mm septa size, black, white or customized colours.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/crew Caps with Septa for 8-425 Screw Neck Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-005', '10-425 Screw Neck 2ml HPLC Autosampler Vial', '1.5-2.0ml wide-mouth 10-425 autosampler vial made from high-quality borosilicate glass. 11.6 x 32mm, clear or amber, 10mm screw neck, suitable for chromatography and micro-insert use, especially where a larger injection range is needed.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/10-425 Screw Neck 2ml HPLC Autosampler Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-006', '10-425 Screw Caps with Septa', 'Polypropylene caps for 10-425 screw vials with excellent sealing characteristics and chemical resistance. Available with 7mm centre hole or closed top, PTFE/silicone septa, 10 x 1.5mm septa size, black or customized colours.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/10-425 Screw Caps with Septa.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-007', '11mm Crimp Top 2ml Autosampler Vial', '1.5-2.0ml crimp-top autosampler vial commonly used for gas sampling and laboratory analysis. 11.6 x 32mm, clear or amber borosilicate glass, 11mm crimp neck, compatible with 250ul/300ul inserts.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/11mm Crimp Top 2ml Autosampler Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-008', '11mm Crimp Top Caps with Septa', 'Aluminum crimp caps with septa for 11mm crimp-top vials. Designed to squeeze the septum between vial rim and aluminum cap to form a tight seal, reduce evaporation and support autosampler compatibility.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/11mm Crimp Top Caps with Septa.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
