INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-010', '11mm Snap Top Caps with Septa', 'Polypropylene snap caps for 11mm snap-ring vials. Pre-assembled septa, secure audible click seal, compatible with Aijiren and other snap-ring vials; mainly recommended for HPLC applications.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/11mm Snap Top Caps with Septa.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
