INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-012', '18mm Screw Headspace Vial', 'Headspace vial for top-space/gas chromatography analysis of volatile and semi-volatile samples. Available 10ml and 20ml, 22.5 x 46mm or 22.5 x 75mm, clear/amber borosilicate glass, 18mm precision screw neck and magnetic precision screw metal cap.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/18mm Screw Headspace Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
