INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-014', 'Butyl Rubber Stopper for 20mm Crimp Vials', 'Butyl rubber stopper for 20mm crimp vials. Provides airtight sealing with chemical stability, heat resistance, ozone resistance and aging resistance for headspace vial closure systems.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/Butyl Rubber Stopper for 20mm Crimp Vials.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
