INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-016', '20mm 20ml Crimp Headspace Vial', '20ml crimp-top headspace vial widely used in Headspace, GC and GCMS applications. 22.5 x 75mm, clear or amber borosilicate glass, flat or round bottom, 20mm crimp neck.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/20mm 20ml Crimp Headspace Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-017', '18mm 20ml Screw Headspace Vial', '20ml precision screw headspace vial with 18mm magnetic screw cap. Designed for threaded vial systems and compatible with instruments such as CTC PAL, Varian, Gerstel, Atas, Shimadzu and Agilent.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/18mm 20ml Screw Headspace Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-018', '20mm 10ml Crimp Top Headspace Vial', '10ml crimp-top headspace vial for headspace and GC workflows. Uses 20mm crimp closure and borosilicate glass construction for high-temperature sample analysis.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/20mm 10ml Crimp Top Headspace Vial.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-019', '18mm 10ml Screw Headspace Vials', '10ml precision screw headspace vial with 18mm magnetic screw cap. Used for automated headspace sampling and top-space chromatography analysis.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/18mm 10ml Screw Headspace Vials.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-020', '20mm 6ml Crimp Top Headspace Vials for Karl Fischer', '6ml crimp-top headspace vial for Karl Fischer/headspace use. Made from borosilicate glass for chemical stability and closed with 20mm crimp closure.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 pack', 0, '/products/20mm 6ml Crimp Top Headspace Vials for Karl Fischer.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-021', 'Endodontic Rotary', 'Endodontic rotary machine/endo motor used during root canal therapy to clean and shape tooth root canals using flexible nickel-titanium files. Typical speed 100-1,500 RPM, torque 0.2-7.5 Ncm, continuous/reciprocating/adaptive torque motion modes.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Endodontic Rotary .jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-022', 'Sputum Aspirator - Portable Phlegm Suction Unit (Suction)', 'Portable suction unit that creates controlled negative pressure to clear mucus, blood or secretions from a patient''s airway. Typical flow 15-30 LPM, adjustable maximum negative pressure about -0.070 to -0.090 MPa, 1000ml collection bottle and oil-free pump.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Sputum Aspirator – Portable Phlegm Suction Unit (Suction).jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-023', 'Dental Chair', 'Electrically operated ergonomic dental chair with integrated dental unit systems for patient positioning, water, air and suction. Specifications include 110V-240V, 0.55MPa air pressure, 0.2-0.4MPa water pressure, 440-860mm height range, 185cm max length, and optional handpieces/scaler/curing light/compressor/suction pump/massage.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Dental Chair.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-024', 'Dental Handpiece Kit', 'Comprehensive kit of handheld rotary dental instruments powered by air or electricity for cutting, polishing and removing tooth structure. Includes 2 high-speed standard handpieces, contra angle, straight head, low-speed air motor and standard cartridge.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Dental Handpiece Kit .jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-025', 'Ergonomic Dental Stools', 'Adjustable stools for dentists, hygienists and dental assistants. Designed for procedure comfort with adjustable height, backrest support, cushioning, caster movement, stable five-leg powder-coated aluminum base and height mechanism options.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Dental Stool.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-026', 'Air/Water Syringe', 'Dental 3-way syringe attached to a dental unit to deliver air, water or fine mist. Used to rinse debris, dry tooth surfaces, improve visibility and cool teeth during procedures. Features push-button controls, 360-degree swivel tips and autoclavable metal tips.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Air:Water Syringe.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-027', 'Pulp Tester', 'Battery-operated dental device used to determine whether the nerve inside a tooth is alive or healthy. Listed output voltage 9.0V DC, output current 90mA, Class II equipment.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Dental Products', '1 unit', 0, '/products/Pulp Tester.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
