INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-066', 'Cell Culture Cover Glass', 'Borosilicate 3.3 cell culture cover glass with TC treatment for IHC, confocal experiments, cell culture and fluorescence microscopy. Pre-clean, pre-autoclaved, RNase/DNase/pyrogen free, non-cytotoxic and solvent-resistant.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 pack', 0, '/products/Cell Culture Cover Glass .jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-067', 'Cell Spreaders', 'PP autoclavable spreaders for spreading and dispersing liquids on agar plates. Available triangle, T-shape and L-shape formats, sterile or non-sterile, in blue/yellow/white depending on type.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 pack', 0, '/products/Cell Spreaders.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-068', 'Classical Swabs', 'Swabs for sampling surfaces and wide orifices such as skin, mouth, nose and throat. Available wooden or plastic sticks, cotton/viscose/polyester/foam tips, sterile or non-sterile, bulk packed.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 pack', 0, '/products/Classical swabs.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
