INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-071', 'Environmental Surface Collection Kit', 'Environmental surface collection kit for collecting surface samples during microbiological monitoring and contamination checks. Designed for workplace, production, laboratory and hygiene monitoring workflows where surface specimens need to be collected and transported for testing.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 pack', 0, '/products/Environmental Surface Collection Kit.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('PDF-072', 'Bacteriological Petri Dishes', 'Bacteriological petri dishes for microbiological culture work, bacterial growth, colony observation and laboratory plating applications. Used for agar preparation, inoculation, incubation and routine microbiology testing workflows.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 pack', 0, '/products/Bacteriological Petri Dishes.png') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
