INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('DE-010', 'Surface Disinfectants + Barriers', 'Surface disinfectants and barrier products such as chair covers and light-handle covers for infection control.', '17453c2a-723b-fa5d-6c3c-4e22e126c4a5', 'Surface Disinfectants + Barriers', '1 unit', 0, '/products/Surface Disinfectants.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('BCN-001', 'Disposable Blood Collection Needles', 'Gongdong disposable blood collection needles for vacuum blood collection workflows.', '3bcb04bd-0fab-5cd9-353b-eb273946938e', 'Blood Collection Needles', '1 pack', 0, '/drive-download-20260630T094004Z-3-001/disposable vacuum blood collection tube/采血针.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-257', 'Transparent PE Tape 2.5cm x 5m', 'Breathable, water-resistant surgical tape (2.5 cm x 5 m) with a micro-perforated clear polyethylene backing and hypoallergenic medical-grade acrylic adhesive. The transparent film lets clinicians monitor puncture sites and wounds without removing the tape, and the perforations allow easy bi-directional hand tearing with minimal residue on removal.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/transparent-pe-tape.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-258', 'Sterile Hypodermic Needles 23G', 'Medical-grade 23G (0.6 mm) sterile hypodermic needle with a fine stainless-steel cannula, available in 25 mm (1") and 38 mm (1.5") lengths. Internationally colour-coded blue and universally compatible with both Luer Lock and Luer Slip syringes.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Hypodermic Products', '1 unit', 0, '/batch2/sterile-hypodermic-needles-23g.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-259', 'Non-Woven Gauze Non-Sterile 100 x 100mm', 'Highly absorbent, lint-free synthetic non-woven swabs measuring 100 mm x 100 mm, available in 4-ply or 8-ply. Soft, breathable and gentle on sensitive skin.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/non-woven-gauze-100x100.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-260', 'Wooden Tongue Depressor 150 x 17 x 1.6mm', 'Flat, biodegradable medical blade made from sustainable wood with polished rounded ends for atraumatic examination of the mouth and oropharynx. 100% compostable.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/wooden-tongue-depressor.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-261', 'Sterile 21-Gauge Green Hypodermic Needle', 'Sterile 21G needle (approx. 0.80 mm outer diameter) in 25 mm and 38/40 mm lengths. Ethylene-oxide sterilised, non-pyrogenic, single use, latex-free, with a universal Luer Lock / Luer Slip polypropylene hub.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Hypodermic Products', '1 unit', 0, '/batch2/sterile-hypodermic-needle-21g.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-262', 'Golden Hands Nitrile Gloves - Blue', 'Premium 100% latex-free synthetic nitrile examination gloves offering three times the puncture resistance of latex, excellent chemical protection and high tactile sensitivity. Ambidextrous, beaded cuff, micro-textured fingers and palms, approx. 3.5g weight profile.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/golden-hands-nitrile-gloves-blue.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-263', '20G x 1" Disposable Needle', 'Sterile single-use hypodermic needle, 20G (approx. 0.9 mm) x 1 inch (25 mm), with a yellow standardised hub, surgical-grade stainless steel cannula and polypropylene hub. Individually blister-packed and ethylene-oxide sterilised.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Hypodermic Products', '1 unit', 0, '/batch2/disposable-needle-20g.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-264', 'Golden Hands Latex Powder-Free Gloves', 'Premium natural rubber latex examination gloves, powder-free, non-sterile and ambidextrous with a textured finish and beaded cuff. Chlorinated/polymer coated with low water-soluble protein (<50 ug/dm2). Conforms to ASTM D3578-10. Sizes S-XL, 100 gloves per dispenser box.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/golden-hands-latex-powder-free-gloves.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-265', 'Golden Hands Black Nitrile Gloves', 'Premium 100% latex-free black nitrile gloves designed to camouflage blood, oil and dirt. Thicker than standard nitrile for durability, fully textured for grip, waterproof and chemical resistant. Conforms to ASTM D3578-10, EN455, ISO 9001:2015 and ISO 13485:2016. Sizes S-XL.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/golden-hands-black-nitrile-gloves.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-266', 'Safety Goggles', 'Tight-fitting PPE goggles that seal around the eyes with an elastic strap, preventing chemical splashes, fine dust and projectiles from entering from the sides. High-impact polycarbonate lenses with direct/indirect venting options and soft flexible PVC or foam padding for long-wear comfort.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/safety-goggles.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-267', 'Disposable Alcohol Swabs', 'Small sterile non-woven pads saturated with 70% isopropyl alcohol, individually sealed in airtight foil packets to prevent evaporation. Soft 2-ply or 4-ply viscose/polyester material.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/disposable-alcohol-swabs.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-268', 'Venous Blood Collection Needles 21G', 'Standard multi-sample venous blood collection needle with an ultra-sharp, silicone-coated bevel and rubber sleeve on the tube end to prevent leakage during tube changes. Outer diameter 0.8 mm, lengths 25-38 mm, green colour-coded hub. Threads into standard single-use tube holders.', '3bcb04bd-0fab-5cd9-353b-eb273946938e', 'Blood Collection Needles', '1 unit', 0, '/batch2/venous-blood-collection-needle-21g.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-269', 'PE (Polyethylene) Bandages', 'Flexible, waterproof and breathable adhesive strips with a polyethylene film backing (50-65 GSM), hypoallergenic medical-grade adhesive and a non-stick absorbent pad. Available in standard strips (72 x 19 mm / 76 x 25 mm), joint patches and spot sizes.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/pe-bandages.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-270', 'Thermal Sticker 34x50mm - 3 Part 3 To View White Blank 1,500', 'Direct thermal label 34 mm x 50 mm, laid out 3 across per row (3 to view), 1,500 labels per roll. Plain white top-coated direct thermal stock requiring no ink or ribbon, permanent adhesive, perforated between rows, 1"-1.5" core.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/thermal-sticker-34x50.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-271', 'Cliplock Container 45ml P/P (Laminar Flow) with NHLS Label - Unit 800', 'Precision-moulded polypropylene specimen container holding up to 35 ml, approx. 39 mm x 58 mm, with a tight screw cap that locks in odours and resists leaks. Clear volume graduations and a frosted patient-ID panel. Supplied in bulk boxes of 800.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/cliplock-container-45ml.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-272', 'Tube Capillary PLN VL 100', 'Narrow plain (untreated, no anticoagulant) capillary tubes that draw approx. 70 uL by capillary action. Borosilicate or soda-lime glass construction, supplied in vials of 100 tubes.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 unit', 0, '/batch2/tube-capillary-pln-vl-100.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-273', 'Forcep BL/BL Stainless Steel 150mm - Qty 11', 'Pack of 11 reusable 150 mm (6") stainless steel laboratory forceps in grade 304/410 steel. Straight body with blunt-on-blunt, non-traumatic fluted tips and ribbed handles for a secure, slip-free grip.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Laboratory Instruments & Accessories', '1 unit', 0, '/batch2/forcep-stainless-steel-150mm.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-274', 'Health Care Risk Waste Labels 86x130mm - 26 Rolls of 100', 'Self-adhesive high-visibility biohazard labels, 86 mm x 130 mm, supplied on rolls of 100. Printed with the universal biohazard symbol in fade-resistant high-contrast ink on durable, smear-proof, water-resistant material.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/health-care-risk-waste-labels.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-275', 'Cooler Box Polystyrene 6 Pack', 'Lightweight, high-insulation cooler box moulded from rigid expanded polystyrene (EPS) with a tight-fitting lid. Approx. 260 x 180 x 205 mm exterior / 235 x 158 x 135 mm interior.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Laboratory Instruments & Accessories', '1 unit', 0, '/batch2/cooler-box-polystyrene-6pack.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-276', 'Pipette PIPETMAN Neo P100N', 'Manual single-channel air-displacement micropipette covering 10-100 uL (other ranges available: 1-10 uL, 2-20 uL, 100-1000 uL). Redesigned springs reduce pipetting force by up to 50%, PVDF handle resists chemicals, stainless steel tip ejector, colour-coded push-button. Exceeds ISO 8655.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Laboratory Instruments & Accessories', '1 unit', 0, '/batch2/pipette-pipetman-neo-p100n.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-277', 'Disposable Lab Coat, Waterproof Chemical Resistant (10s)', 'Single-use protective garment in lightweight fluid-repellent non-woven spunbond polypropylene or PE-coated fabric. Breathable, with front closure, long sleeves and elasticated or open cuffs. Packed in sets of 10.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/disposable-lab-coat.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-278', 'Sediplast Tubes + Pipettes (1000/Box)', 'Closed disposable ESR testing system using the Westergren method. Each unit comprises a reservoir tube pre-filled with 0.2 mL of 3.8% sodium citrate and a graduated pipette that auto-zeros the blood column on insertion, with a pierceable diaphragm for a hermetic, aerosol-free seal. 1,000 per box.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/sediplast-tubes-pipettes.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-279', 'Cotton Wool Balls (500gm)', 'Soft, highly absorbent puffs of 100% pure natural cotton, approx. 500 x 1 g balls per bag. Hypoallergenic, lint-reduced and free of fragrances, dyes and synthetic fillers.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical & Medical Disposables', '1 unit', 0, '/batch2/cotton-wool-balls-500gm.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-280', 'Mutton Cloth White B Grade', '100% cotton unbleached, un-dyed stockinette wiping cloth. B-Grade denotes slight weaving imperfections or off-white variation, making it a cost-effective bulk cleaning solution. Highly stretchy, breathable, absorbent, washable and easily cut to size.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Paper & Wiping Products', '1 unit', 0, '/batch2/mutton-cloth-white-b-grade.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-281', 'Tissues x 100', 'Dispenser box of 100 facial tissue sheets, typically 2-ply, made from high-quality absorbent pulp with interleaved pop-up dispensing. Sheets measure approx. 18.5-21.5 cm. Hypoallergenic and perfume-free.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Paper & Wiping Products', '1 unit', 0, '/batch2/tissues-x100.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-282', 'Test Tubes Soda Glass (12 x 75mm)', 'Cylindrical round-bottom soda-lime glass tubes, 12 mm diameter x 75 mm length, approx. 5-6 mL capacity with 0.6-1.0 mm wall thickness and a rimless straight edge.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Bottle Consumables', '1 unit', 0, '/batch2/test-tubes-soda-glass-12x75.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-283', 'Surgical Blade Size 24 (100/Box)', 'No. 24 surgical blade with a large semi-circular curved cutting edge, supplied in boxes of 100 sterile, individually foil-wrapped units with anti-corrosion paper. Carbon steel or stainless steel, gamma/Cobalt-60 sterilised. Fits scalpel handles No. 4, 4L and 6B.', '547f883b-a708-f08a-3a50-b06e83685bcc', 'Surgical Products', '1 unit', 0, '/batch2/surgical-blade-size-24.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-284', 'Timer Jumbo Up/Down 4 Channel', 'Four independent timing channels with count-up and count-down modes up to 99:59:59 at 1-second resolution. Oversized jumbo LCD, approx. 70 dB alarm that auto-switches to count-up, 12/24-hour clock, fold-out stand, magnetic back and pocket clip.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Laboratory Instruments & Accessories', '1 unit', 0, '/batch2/timer-jumbo-updown-4channel.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-285', 'Ribbon Cassette for PIX200', 'Amano CE-315151 black nylon fabric ribbon cartridge yielding approximately 8,000 prints. Snap-in replacement compatible with Amano PIX-10/20/21/200/3000, TCX-21 and EX-3000 series time clocks.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Laboratory Instruments & Accessories', '1 unit', 0, '/batch2/ribbon-cassette-pix200.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-286', 'Biological Spill Kit', 'Complete kit for safe cleanup and disinfection of biohazardous material such as blood, vomit and urine. Contains personal protective equipment, containment and absorption materials and approved disinfectant, housed in a clearly labelled waterproof carry container.', '42225f65-2723-bf21-1ff1-6f513c43a865', 'Laboratory Instruments & Accessories', '1 unit', 0, '/batch2/biological-spill-kit.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-287', 'SP Bags HD White (100/pkt)', 'High-density polyethylene / polypropylene bags with a rigid, high-tensile feel, 30-45 microns for light use or approx. 74 GSM heavy-duty. Unprinted white, often with cut-out handles or sealed bottoms. Sold in 100-packs.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Paper & Wiping Products', '1 unit', 0, '/batch2/sp-bags-hd-white.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-288', 'Tidy Control 1 Ply 150 (6 x 150m)', 'High-capacity single-ply rolled hand towel, 150 m per roll, 6 rolls per pack, approx. 200 mm wide in 21-35 gsm industrial towel grade. Designed for auto-cut and reflex pull-and-tear dispensers. Approx. 6.5 kg per bale.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Paper & Wiping Products', '1 unit', 0, '/batch2/tidy-control-1ply-150.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-289', 'T/T Stoppers 11-13mm D (1000/pkt)', 'Flexible laboratory closures fitting tubes with an 11-13 mm outer diameter, moulded from medical-grade virgin PE/LDPE. Ribbed or flanged wing-style design gives a dual-ring, leak-proof seal. Bulk packs of 1,000.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/tt-stoppers-11-13mm.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-290', 'Specimen Bag (50 Bags Per Roll x 40 Rolls = 1 Bale)', 'Clear heavy-duty LDPE specimen transport pouch with an attached document sleeve, 2-ply/3-wall construction, 40-50 micron thickness for puncture resistance. 50 tear-off bags per roll, 40 rolls (2,000 bags) per bale.', '201c68f6-d54b-612a-70ad-5653d088b92c', 'Laboratory Plastic Consumables', '1 unit', 0, '/batch2/specimen-bag-roll.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-291', 'Profinish 5L', 'Premium wax-based floor sealer (product code P07305) for vinyl and stone flooring. A blend of waxes, polymers, plasticizers and preservatives. Milky liquid, pH 8.5 +/- 0.5, specific gravity 1.030 g/ml at 20 C, 22% total solids.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Cleaning Chemicals', '1 unit', 0, '/batch2/profinish-5l.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-292', 'Probuff 5L', 'Ready-to-use floor maintenance spray buff that removes soil, scuff and heel marks while restoring shine on sealed floors. Milky green liquid, pH 9.0 +/- 0.5, specific gravity 1.000 g/ml at 20 C. 5 litre pack.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Cleaning Chemicals', '1 unit', 0, '/batch2/probuff-5l.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-293', 'Domestos 3LT', 'Heavy-duty concentrated thick bleach disinfectant that clings to vertical surfaces. 0.5% sodium hypochlorite, highly alkaline (approx. pH 11.5 at recommended dilution), 3 L canister. Kills 99.9% of bacteria, fungi, viruses and spores.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Cleaning Chemicals', '1 unit', 0, '/batch2/domestos-3lt.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-294', '3LT Jik Regular', 'Unfragranced multipurpose thin bleach based on sodium hypochlorite, dilutable for laundry and household disinfection. 3 litres, approx. 3.25 kg per bottle. Kills 99.9% of germs and viruses on hard surfaces.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Cleaning Chemicals', '1 unit', 0, '/batch2/jik-regular-3lt.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
INSERT INTO products (sap, name, description, category_id, raw_category, inner_moq, price, image_url) VALUES ('LM-B2-295', 'Handy Andy 750ml', 'Multipurpose cream cleaner using 100% natural cleaning micro-particles to lift stubborn dirt, grease and limescale without scratching. Phosphate-free surfactants and biodegradable fragrance in a 750 ml recycled-plastic squeeze bottle.', '7fd906fc-2bca-8df0-35b5-8cb05e88c8a7', 'Cleaning Chemicals', '1 unit', 0, '/batch2/handy-andy-750ml.jpg') ON CONFLICT (sap) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, category_id=EXCLUDED.category_id, raw_category=EXCLUDED.raw_category, price=EXCLUDED.price, image_url=EXCLUDED.image_url;
